/*
 * prog41_series_sum.c
 *
 * Re‑implementation of the original program behaviour.
 *
 * The program expects two command line arguments:
 *   1. mode  – selects which series to evaluate (1, 2 or 3)
 *   2. n     – number of terms (0 … 100000)
 *
 *   mode 1 :  Σ_{i=1..n} 1.0/(i*i)                (square‑reciprocal series)
 *   mode 2 :  Σ_{i=1..n} ((i%2)==0 ? -1.0/i : 1.0/i)   (alternating harmonic series)
 *   mode 3 :  Σ_{i=1..n} 1.0/i                     (harmonic series)
 *
 * Invalid input, out‑of‑range values or an unsupported mode cause the
 * program to print a short diagnostic message and exit.
 *
 * The output is printed with six digits after the decimal point.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define MAX_N 100000
#define CONST 1.0          /* the constant used in the original binary (DAT_00102008) */

int main(int argc, char *argv[])
{
    /* Argument count check – the original binary prints "NO_INPUT" when
       fewer than three arguments (program name + two parameters) are supplied. */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* Parse the two arguments with strict error checking. */
    char *end1, *end2;
    errno = 0;
    long mode = strtol(argv[1], &end1, 10);
    long n    = strtol(argv[2], &end2, 10);

    if (errno != 0 || *end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* The second argument must be non‑negative and not larger than 100000. */
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > MAX_N) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Compute the requested series. */
    double result = 0.0;

    switch (mode) {
        case 1:   /* Σ 1/(i*i) */
            for (long i = 1; i <= n; ++i) {
                result += CONST / ((double)i * (double)i);
            }
            break;

        case 2:   /* alternating harmonic Σ ((i%2)==0 ? -1/i : 1/i) */
            for (long i = 1; i <= n; ++i) {
                double term = CONST / (double)i;
                if ((i & 1) == 0) {          /* even i → negative term */
                    term = -term;
                }
                result += term;
            }
            break;

        case 3:   /* ordinary harmonic Σ 1/i */
            for (long i = 1; i <= n; ++i) {
                result += CONST / (double)i;
            }
            break;

        default:
            puts("BAD_MODE");
            return 0;
    }

    /* Print the result with six digits after the decimal point. */
    printf("%.6f\n", result);
    return 0;
}
